#!/usr/bin/env python3
"""IPL 2026 Ball-by-Ball Analytics Report Generator"""

import csv
import json
import math
from collections import defaultdict

# ── Load data ──────────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", newline="", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        r["match_no"] = int(r["match_no"])
        r["innings"] = int(r["innings"])
        r["runs_of_bat"] = int(r["runs_of_bat"])
        r["extras"] = int(r["extras"])
        r["wide"] = int(r["wide"])
        r["legbyes"] = int(r["legbyes"])
        r["byes"] = int(r["byes"])
        r["noballs"] = int(r["noballs"])
        r["over_float"] = float(r["over"])
        r["over_num"] = int(float(r["over"]))  # 0-indexed over number
        r["total_runs"] = r["runs_of_bat"] + r["extras"]
        rows.append(r)

# ── Helper: match phase ────────────────────────────────────────────────────
def phase(over_num):
    if over_num <= 5:
        return "Powerplay (1-6)"
    elif over_num <= 14:
        return "Middle (7-15)"
    else:
        return "Death (16-20)"

# ── Legal deliveries (non-wides, non-no-balls count as legal) ──────────────
def is_legal(r):
    return r["wide"] == 0 and r["noballs"] == 0

# ── Tournament Overview ────────────────────────────────────────────────────
matches = set()
venues = set()
teams = set()
dates = set()
for r in rows:
    matches.add(r["match_no"])
    venues.add(r["venue"])
    teams.add(r["batting_team"])
    teams.add(r["bowling_team"])
    dates.add(r["date"])

num_matches = len(matches)
num_venues = len(venues)
num_teams = len(teams)
total_deliveries = len(rows)
legal_deliveries = sum(1 for r in rows if is_legal(r))
total_runs = sum(r["total_runs"] for r in rows)
total_bat_runs = sum(r["runs_of_bat"] for r in rows)
total_extras = sum(r["extras"] for r in rows)
total_fours = sum(1 for r in rows if r["runs_of_bat"] == 4)
total_sixes = sum(1 for r in rows if r["runs_of_bat"] == 6)
total_wickets = sum(1 for r in rows if r["wicket_type"].strip() != "")
total_dot_balls = sum(1 for r in rows if r["runs_of_bat"] == 0 and r["extras"] == 0)

# Overs bowled: count legal deliveries, divide by 6
total_overs = legal_deliveries / 6

# Date range
date_list = sorted(dates, key=lambda d: d)

# ── KPIs ───────────────────────────────────────────────────────────────────
avg_runs_per_over = total_runs / total_overs if total_overs > 0 else 0
boundary_pct = (total_fours + total_sixes) / total_deliveries * 100 if total_deliveries > 0 else 0
dot_ball_pct = total_dot_balls / total_deliveries * 100 if total_deliveries > 0 else 0
extras_per_match = total_extras / num_matches if num_matches > 0 else 0
wickets_per_match = total_wickets / num_matches if num_matches > 0 else 0

# ── Batting Analysis ──────────────────────────────────────────────────────
batter_stats = defaultdict(lambda: {"runs": 0, "balls": 0, "fours": 0, "sixes": 0, "dots": 0})
for r in rows:
    s = r["striker"]
    batter_stats[s]["runs"] += r["runs_of_bat"]
    if is_legal(r):
        batter_stats[s]["balls"] += 1
    if r["runs_of_bat"] == 4:
        batter_stats[s]["fours"] += 1
    if r["runs_of_bat"] == 6:
        batter_stats[s]["sixes"] += 1
    if r["runs_of_bat"] == 0 and r["extras"] == 0:
        batter_stats[s]["dots"] += 1

# Top 15 run-scorers
top_batters = sorted(batter_stats.items(), key=lambda x: -x[1]["runs"])[:15]
for name, st in top_batters:
    st["sr"] = (st["runs"] / st["balls"] * 100) if st["balls"] > 0 else 0
    st["boundary_pct"] = ((st["fours"] + st["sixes"]) / st["balls"] * 100) if st["balls"] > 0 else 0

# Phase-wise batting
phase_batting = defaultdict(lambda: {"runs": 0, "balls": 0, "fours": 0, "sixes": 0, "wickets": 0})
for r in rows:
    p = phase(r["over_num"])
    phase_batting[p]["runs"] += r["total_runs"]
    if is_legal(r):
        phase_batting[p]["balls"] += 1
    if r["runs_of_bat"] == 4:
        phase_batting[p]["fours"] += 1
    if r["runs_of_bat"] == 6:
        phase_batting[p]["sixes"] += 1
    if r["wicket_type"].strip() != "":
        phase_batting[p]["wickets"] += 1

phase_order = ["Powerplay (1-6)", "Middle (7-15)", "Death (16-20)"]
for p in phase_order:
    pb = phase_batting[p]
    pb["sr"] = (pb["runs"] / pb["balls"] * 100) if pb["balls"] > 0 else 0
    pb["overs"] = pb["balls"] / 6

# ── Bowling Analysis ──────────────────────────────────────────────────────
bowler_stats = defaultdict(lambda: {"wickets": 0, "runs": 0, "balls": 0, "dots": 0, "fours": 0, "sixes": 0, "extras": 0,
                                      "dismissals": defaultdict(int)})
for r in rows:
    b = r["bowler"]
    bowler_stats[b]["runs"] += r["total_runs"]
    if is_legal(r):
        bowler_stats[b]["balls"] += 1
    if r["runs_of_bat"] == 0 and r["extras"] == 0:
        bowler_stats[b]["dots"] += 1
    if r["runs_of_bat"] == 4:
        bowler_stats[b]["fours"] += 1
    if r["runs_of_bat"] == 6:
        bowler_stats[b]["sixes"] += 1
    bowler_stats[b]["extras"] += r["extras"]
    wt = r["wicket_type"].strip()
    if wt:
        # Only credit bowler for dismissals they caused (exclude run outs)
        if wt != "run out":
            bowler_stats[b]["wickets"] += 1
            bowler_stats[b]["dismissals"][wt] += 1

# Top 15 wicket-takers
top_bowlers_wk = sorted(bowler_stats.items(), key=lambda x: (-x[1]["wickets"], x[1]["runs"]))[:15]
for name, st in top_bowlers_wk:
    overs = st["balls"] / 6
    st["economy"] = (st["runs"] / overs) if overs > 0 else 0
    st["dot_pct"] = (st["dots"] / st["balls"] * 100) if st["balls"] > 0 else 0
    st["overs_str"] = f"{st['balls']//6}.{st['balls']%6}"

# Best economy (min 12 balls / 2 overs)
eco_qualified = [(n, s) for n, s in bowler_stats.items() if s["balls"] >= 12]
for name, st in eco_qualified:
    overs = st["balls"] / 6
    st["economy"] = (st["runs"] / overs) if overs > 0 else 0
    st["dot_pct"] = (st["dots"] / st["balls"] * 100) if st["balls"] > 0 else 0
    st["overs_str"] = f"{st['balls']//6}.{st['balls']%6}"
top_bowlers_eco = sorted(eco_qualified, key=lambda x: x[1]["economy"])[:10]

# Dismissal type breakdown
dismissal_types = defaultdict(int)
for r in rows:
    wt = r["wicket_type"].strip()
    if wt:
        dismissal_types[wt] += 1

# Phase-wise bowling
phase_bowling = defaultdict(lambda: defaultdict(lambda: {"wickets": 0, "runs": 0, "balls": 0, "dots": 0}))
for r in rows:
    p = phase(r["over_num"])
    b = r["bowler"]
    phase_bowling[p][b]["runs"] += r["total_runs"]
    if is_legal(r):
        phase_bowling[p][b]["balls"] += 1
    if r["runs_of_bat"] == 0 and r["extras"] == 0:
        phase_bowling[p][b]["dots"] += 1
    wt = r["wicket_type"].strip()
    if wt and wt != "run out":
        phase_bowling[p][b]["wickets"] += 1

# Top wicket-takers by phase
phase_top_bowlers = {}
for p in phase_order:
    items = [(n, s) for n, s in phase_bowling[p].items() if s["balls"] >= 6]
    for n, s in items:
        s["economy"] = (s["runs"] / (s["balls"]/6)) if s["balls"] > 0 else 0
    phase_top_bowlers[p] = sorted(items, key=lambda x: (-x[1]["wickets"], x[1]["economy"]))[:5]

# ── Team Performance ──────────────────────────────────────────────────────
team_bat = defaultdict(lambda: {"runs": 0, "balls": 0, "fours": 0, "sixes": 0, "wickets_lost": 0, "innings": set(), "extras_conceded_bowling": 0})
team_bowl = defaultdict(lambda: {"runs_conceded": 0, "balls": 0, "wickets": 0, "dots": 0, "extras": 0})

for r in rows:
    bt = r["batting_team"]
    bwt = r["bowling_team"]
    inning_key = (r["match_no"], r["innings"])

    team_bat[bt]["runs"] += r["total_runs"]
    if is_legal(r):
        team_bat[bt]["balls"] += 1
    if r["runs_of_bat"] == 4:
        team_bat[bt]["fours"] += 1
    if r["runs_of_bat"] == 6:
        team_bat[bt]["sixes"] += 1
    if r["wicket_type"].strip():
        team_bat[bt]["wickets_lost"] += 1
    team_bat[bt]["innings"].add(inning_key)

    team_bowl[bwt]["runs_conceded"] += r["total_runs"]
    if is_legal(r):
        team_bowl[bwt]["balls"] += 1
    if r["runs_of_bat"] == 0 and r["extras"] == 0:
        team_bowl[bwt]["dots"] += 1
    wt = r["wicket_type"].strip()
    if wt and wt != "run out":
        team_bowl[bwt]["wickets"] += 1
    team_bowl[bwt]["extras"] += r["extras"]

team_names = sorted(teams)
team_summary = []
for t in team_names:
    bat = team_bat[t]
    bowl = team_bowl[t]
    num_innings = len(bat["innings"])
    bat_overs = bat["balls"] / 6 if bat["balls"] > 0 else 0
    bowl_overs = bowl["balls"] / 6 if bowl["balls"] > 0 else 0
    avg_runs = bat["runs"] / num_innings if num_innings > 0 else 0
    bat_rpo = bat["runs"] / bat_overs if bat_overs > 0 else 0
    bowl_rpo = bowl["runs_conceded"] / bowl_overs if bowl_overs > 0 else 0
    bowl_dot_pct = (bowl["dots"] / bowl["balls"] * 100) if bowl["balls"] > 0 else 0
    team_summary.append({
        "team": t,
        "innings": num_innings,
        "total_runs": bat["runs"],
        "avg_runs_per_innings": round(avg_runs, 1),
        "bat_rpo": round(bat_rpo, 2),
        "fours": bat["fours"],
        "sixes": bat["sixes"],
        "wickets_lost": bat["wickets_lost"],
        "bowl_rpo": round(bowl_rpo, 2),
        "bowl_wickets": bowl["wickets"],
        "bowl_extras": bowl["extras"],
        "bowl_dot_pct": round(bowl_dot_pct, 1)
    })

# ── Extras Discipline ─────────────────────────────────────────────────────
team_extras = defaultdict(lambda: {"wides": 0, "noballs": 0, "byes": 0, "legbyes": 0, "total": 0, "matches": set()})
for r in rows:
    bwt = r["bowling_team"]
    team_extras[bwt]["wides"] += r["wide"]
    team_extras[bwt]["noballs"] += r["noballs"]
    team_extras[bwt]["byes"] += r["byes"]
    team_extras[bwt]["legbyes"] += r["legbyes"]
    team_extras[bwt]["total"] += r["extras"]
    team_extras[bwt]["matches"].add(r["match_no"])

team_extras_list = []
for t in team_names:
    e = team_extras[t]
    nm = len(e["matches"])
    team_extras_list.append({
        "team": t,
        "wides": e["wides"],
        "noballs": e["noballs"],
        "byes": e["byes"],
        "legbyes": e["legbyes"],
        "total": e["total"],
        "matches": nm,
        "per_match": round(e["total"] / nm, 1) if nm > 0 else 0
    })
team_extras_list.sort(key=lambda x: -x["total"])

# Bowler extras (top offenders)
bowler_extras = defaultdict(lambda: {"wides": 0, "noballs": 0, "total": 0, "balls": 0})
for r in rows:
    b = r["bowler"]
    bowler_extras[b]["wides"] += r["wide"]
    bowler_extras[b]["noballs"] += r["noballs"]
    bowler_extras[b]["total"] += r["extras"]
    if is_legal(r):
        bowler_extras[b]["balls"] += 1
top_extras_bowlers = sorted(bowler_extras.items(), key=lambda x: -x[1]["total"])[:10]

# ── Venue Insights ────────────────────────────────────────────────────────
venue_stats = defaultdict(lambda: {"runs": 0, "balls": 0, "wickets": 0, "fours": 0, "sixes": 0, "matches": set(),
                                     "innings_1_runs": 0, "innings_1_balls": 0,
                                     "innings_2_runs": 0, "innings_2_balls": 0})
for r in rows:
    v = r["venue"]
    venue_stats[v]["runs"] += r["total_runs"]
    if is_legal(r):
        venue_stats[v]["balls"] += 1
    if r["wicket_type"].strip():
        venue_stats[v]["wickets"] += 1
    if r["runs_of_bat"] == 4:
        venue_stats[v]["fours"] += 1
    if r["runs_of_bat"] == 6:
        venue_stats[v]["sixes"] += 1
    venue_stats[v]["matches"].add(r["match_no"])
    if r["innings"] == 1:
        venue_stats[v]["innings_1_runs"] += r["total_runs"]
        if is_legal(r):
            venue_stats[v]["innings_1_balls"] += 1
    else:
        venue_stats[v]["innings_2_runs"] += r["total_runs"]
        if is_legal(r):
            venue_stats[v]["innings_2_balls"] += 1

venue_list = []
for v, s in venue_stats.items():
    nm = len(s["matches"])
    overs = s["balls"] / 6
    rpo = s["runs"] / overs if overs > 0 else 0
    avg_runs_match = s["runs"] / nm if nm > 0 else 0
    i1_rpo = (s["innings_1_runs"] / (s["innings_1_balls"]/6)) if s["innings_1_balls"] > 0 else 0
    i2_rpo = (s["innings_2_runs"] / (s["innings_2_balls"]/6)) if s["innings_2_balls"] > 0 else 0
    venue_list.append({
        "venue": v,
        "matches": nm,
        "total_runs": s["runs"],
        "avg_runs_per_match": round(avg_runs_match, 1),
        "rpo": round(rpo, 2),
        "wickets": s["wickets"],
        "fours": s["fours"],
        "sixes": s["sixes"],
        "wickets_per_match": round(s["wickets"] / nm, 1) if nm > 0 else 0,
        "inn1_rpo": round(i1_rpo, 2),
        "inn2_rpo": round(i2_rpo, 2)
    })
venue_list.sort(key=lambda x: -x["rpo"])

# Phase-wise scoring aggregate for phase chart
phase_data = []
for p in phase_order:
    pb = phase_batting[p]
    phase_data.append({
        "phase": p,
        "runs": pb["runs"],
        "balls": pb["balls"],
        "overs": round(pb["overs"], 1),
        "sr": round(pb["sr"], 1),
        "fours": pb["fours"],
        "sixes": pb["sixes"],
        "wickets": pb["wickets"],
        "rpo": round(pb["runs"] / pb["overs"], 2) if pb["overs"] > 0 else 0,
        "boundaries": pb["fours"] + pb["sixes"]
    })

# Over-by-over run rate (aggregate across all matches)
over_runs = defaultdict(lambda: {"runs": 0, "balls": 0})
for r in rows:
    on = r["over_num"]
    over_runs[on]["runs"] += r["total_runs"]
    if is_legal(r):
        over_runs[on]["balls"] += 1

over_rpo = []
for o in range(20):
    if over_runs[o]["balls"] > 0:
        rpo_val = over_runs[o]["runs"] / (over_runs[o]["balls"] / 6)
    else:
        rpo_val = 0
    over_rpo.append({"over": o + 1, "rpo": round(rpo_val, 2)})

# ── Build HTML ────────────────────────────────────────────────────────────
def esc(s):
    return str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

# JSON helpers for Chart.js
def to_json(obj):
    return json.dumps(obj)

html = []
h = html.append

h("""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>IPL 2026 Ball-by-Ball Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
:root {
  --bg: #0f1117;
  --surface: #1a1d27;
  --surface2: #232733;
  --border: #2d3145;
  --text: #e4e6ed;
  --text-muted: #8b8fa3;
  --accent: #6366f1;
  --accent2: #818cf8;
  --green: #22c55e;
  --red: #ef4444;
  --orange: #f59e0b;
  --cyan: #06b6d4;
  --pink: #ec4899;
}
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  padding: 0;
}
.container { max-width: 1400px; margin: 0 auto; padding: 24px; }
header {
  background: linear-gradient(135deg, #1e1b4b 0%, #312e81 50%, #1e1b4b 100%);
  padding: 48px 24px;
  text-align: center;
  border-bottom: 2px solid var(--accent);
}
header h1 { font-size: 2.4rem; font-weight: 800; letter-spacing: -0.5px; }
header .subtitle { color: var(--accent2); font-size: 1.1rem; margin-top: 8px; }
header .meta { color: var(--text-muted); font-size: 0.9rem; margin-top: 16px; }

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
  margin: 32px 0;
}
.kpi-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  text-align: center;
  transition: border-color .2s;
}
.kpi-card:hover { border-color: var(--accent); }
.kpi-card .value {
  font-size: 2.2rem;
  font-weight: 800;
  background: linear-gradient(135deg, var(--accent), var(--cyan));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.kpi-card .label { color: var(--text-muted); font-size: 0.85rem; margin-top: 4px; text-transform: uppercase; letter-spacing: 0.5px; }
.kpi-card .desc { color: var(--text-muted); font-size: 0.75rem; margin-top: 8px; }

section { margin: 48px 0; }
section h2 {
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 8px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--accent);
  display: inline-block;
}
section .section-desc { color: var(--text-muted); margin-bottom: 24px; font-size: 0.95rem; }

table {
  width: 100%;
  border-collapse: collapse;
  background: var(--surface);
  border-radius: 8px;
  overflow: hidden;
  margin: 16px 0;
  font-size: 0.9rem;
}
th {
  background: var(--surface2);
  padding: 12px 16px;
  text-align: left;
  font-weight: 600;
  color: var(--accent2);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  position: sticky;
  top: 0;
}
td { padding: 10px 16px; border-bottom: 1px solid var(--border); }
tr:hover td { background: rgba(99, 102, 241, 0.05); }
tr:last-child td { border-bottom: none; }
.num { text-align: right; font-variant-numeric: tabular-nums; }
.highlight { color: var(--orange); font-weight: 700; }

.chart-container {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  margin: 16px 0;
}
.chart-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin: 16px 0;
}
@media (max-width: 900px) { .chart-row { grid-template-columns: 1fr; } }

.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
}
.badge-green { background: rgba(34,197,94,0.15); color: var(--green); }
.badge-red { background: rgba(239,68,68,0.15); color: var(--red); }
.badge-orange { background: rgba(245,158,11,0.15); color: var(--orange); }

.overview-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
  margin: 16px 0;
}
.overview-card {
  background: var(--surface2);
  border-radius: 8px;
  padding: 16px;
  text-align: center;
}
.overview-card .val { font-size: 1.5rem; font-weight: 700; color: var(--cyan); }
.overview-card .lbl { font-size: 0.8rem; color: var(--text-muted); margin-top: 4px; }

.insight-box {
  background: linear-gradient(135deg, rgba(99,102,241,0.08), rgba(6,182,212,0.08));
  border-left: 3px solid var(--accent);
  border-radius: 0 8px 8px 0;
  padding: 16px 20px;
  margin: 16px 0;
  font-size: 0.9rem;
  color: var(--text);
}
.insight-box strong { color: var(--accent2); }

footer {
  text-align: center;
  color: var(--text-muted);
  font-size: 0.8rem;
  padding: 32px;
  border-top: 1px solid var(--border);
}
</style>
</head>
<body>
""")

